// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.ocrimport timber.log.Timber/** * NOUS — OCR Field Extractor (Module 6 v4 — Step 6.2). * * Extracts structured fields from raw OCR text via regex patterns. Supports * both generic formats (phone, email, URL) and India-specific formats * (PAN, Aadhaar, GSTIN, IFSC, UPI ID, Indian currency). * * ## Regex Patterns (per strategy v3 §"India-First Design") * * | Field | Pattern | Example | * |-------|---------|---------| * | Indian Phone | `\+91[\-\s]?\d{10}` | +91-9876543210 | * | Generic Phone | `\d{10}` | 9876543210 | * | Email | `[\w.+-]+@[\w-]+\.[\w.-]+` | roshan@example.com | * | URL | `https?://\S+` | https://nous.ai | * | PAN | `[A-Z]{5}\d{4}[A-Z]` | ABCDE1234F | * | Aadhaar | `\d{4}[\-\s]?\d{4}[\-\s]?\d{4}` | 1234-5678-9012 | * | GSTIN | `\d{2}[A-Z]{5}\d{4}[A-Z]\d[Z][A-Z\d]` | 27ABCDE1234F1Z5 | * | IFSC | `[A-Z]{4}0\d{6}` | HDFC0001234 | * | UPI ID | `[\w.\-]+@[\w.\-]+` | roshan@okhdfcbank | * | Indian Currency | `₹\s?\d+(?:,\d{3})*(?:\.\d{1,2})?` | ₹1,234.50 | * | Date (Indian) | `\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4}` | 09/07/2026 | * | Time | `\d{1,2}:\d{2}(?::\d{2})?\s*[AP]M?` | 2:30 PM | * * ## Privacy * *  - All extraction runs on-device (no cloud regex APIs). *  - Extracted fields are stored in encrypted Memory (Module 3) — never synced. *  - Government ID numbers (PAN/Aadhaar) are MASKED immediately after extraction *    (only the masked form is persisted). * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Step 6.2: OcrFieldExtractor</a> */class OcrFieldExtractor {    /**     * Extract all structured fields from [fullText].     *     * @param fullText the full OCR text from all blocks.     * @return list of extracted fields (sorted by type, then by start position).     */    fun extract(fullText: String): List<OcrField> {        if (fullText.isBlank()) return emptyList()        val fields = mutableListOf<OcrField>()        // 1. India-specific patterns (high priority — privacy-sensitive).        fields.addAll(extractIndianPhones(fullText))        fields.addAll(extractAadhaar(fullText))        fields.addAll(extractPan(fullText))        fields.addAll(extractGstin(fullText))        fields.addAll(extractIfsc(fullText))        fields.addAll(extractUpiIds(fullText))        fields.addAll(extractIndianCurrency(fullText))        // 2. Generic patterns.        fields.addAll(extractGenericPhones(fullText))        fields.addAll(extractEmails(fullText))        fields.addAll(extractUrls(fullText))        fields.addAll(extractDates(fullText))        fields.addAll(extractTimes(fullText))        fields.addAll(extractMoney(fullText))        // 3. Document-specific patterns (best-effort from text context).        fields.addAll(extractMerchantNames(fullText))        fields.addAll(extractReceiptTotals(fullText))        fields.addAll(extractMedicineNames(fullText))        fields.addAll(extractDoctorNames(fullText))        fields.addAll(extractPersonNames(fullText))        fields.addAll(extractOrganizations(fullText))        // De-duplicate (same type + same value) + sort by start index.        val deduped = fields            .distinctBy { it.type to it.value }            .sortedBy { fullText.indexOf(it.rawText) }        Timber.tag(TAG).d("Extracted ${deduped.size} fields from ${fullText.length} chars of OCR text.")        return deduped    }    // ═══════════════════════════════════════════════════════════════════════════    // 1. India-specific extractors    // ═══════════════════════════════════════════════════════════════════════════    /** Extract Indian phone numbers (+91XXXXXXXXXX). */    internal fun extractIndianPhones(text: String): List<OcrField> {        return INDIAN_PHONE_REGEX.findAll(text).map { match ->            val normalized = match.value.replace(Regex("[\\-\\s]"), "")            OcrField(                type = OcrFieldType.INDIAN_PHONE,                value = normalized,                rawText = match.value,                confidence = 0.95f,            )        }.toList()    }    /** Extract Aadhaar numbers (12 digits, possibly with hyphens/spaces). */    internal fun extractAadhaar(text: String): List<OcrField> {        return AADHAAR_REGEX.findAll(text).map { match ->            val normalized = match.value.replace(Regex("[\\-\\s]"), "")            // Validate: Aadhaar must be 12 digits, not starting with 0 or 1.            val isValid = normalized.length == 12 && normalized.first() !in '0'..'1'            OcrField(                type = OcrFieldType.INDIAN_AADHAAR,                value = normalized,                rawText = match.value,                confidence = if (isValid) 0.92f else 0.50f,            )        }.toList()    }    /** Extract PAN numbers (ABCDE1234F — 5 letters, 4 digits, 1 letter). */    internal fun extractPan(text: String): List<OcrField> {        return PAN_REGEX.findAll(text).map { match ->            OcrField(                type = OcrFieldType.INDIAN_PAN,                value = match.value.uppercase(),                rawText = match.value,                confidence = 0.93f,            )        }.toList()    }    /** Extract GSTIN (15-char: 2 digits + 5 letters + 4 digits + 1 letter + 1 digit + Z + 1 alnum). */    internal fun extractGstin(text: String): List<OcrField> {        return GSTIN_REGEX.findAll(text).map { match ->            OcrField(                type = OcrFieldType.INDIAN_GSTIN,                value = match.value.uppercase(),                rawText = match.value,                confidence = 0.94f,            )        }.toList()    }    /** Extract IFSC codes (4 letters + 0 + 6 digits — e.g., HDFC0001234). */    internal fun extractIfsc(text: String): List<OcrField> {        return IFSC_REGEX.findAll(text).map { match ->            OcrField(                type = OcrFieldType.INDIAN_IFSC,                value = match.value.uppercase(),                rawText = match.value,                confidence = 0.92f,            )        }.toList()    }    /** Extract UPI IDs (name@bank — e.g., roshan@okhdfcbank). */    internal fun extractUpiIds(text: String): List<OcrField> {        return UPI_ID_REGEX.findAll(text).map { match ->            // Filter out emails (UPI IDs typically don't have a TLD like .com).            val isLikelyUpi = !match.value.contains(".com") && !match.value.contains(".org")            if (isLikelyUpi) {                OcrField(                    type = OcrFieldType.INDIAN_UPI_ID,                    value = match.value.lowercase(),                    rawText = match.value,                    confidence = 0.85f,                )            } else {                null            }        }.filterNotNull().toList()    }    /** Extract Indian currency (₹ + amount, with optional commas). */    internal fun extractIndianCurrency(text: String): List<OcrField> {        return INDIAN_CURRENCY_REGEX.findAll(text).map { match ->            val amountStr = match.value                .replace("₹", "")                .replace("Rs.", "", ignoreCase = true)                .replace("Rs ", "", ignoreCase = true)                .replace(",", "")                .trim()            OcrField(                type = OcrFieldType.INDIAN_CURRENCY,                value = amountStr,                rawText = match.value,                confidence = 0.90f,            )        }.toList()    }    // ═══════════════════════════════════════════════════════════════════════════    // 2. Generic extractors    // ═══════════════════════════════════════════════════════════════════════════    /** Extract generic phone numbers (10 digits, not starting with +91). */    internal fun extractGenericPhones(text: String): List<OcrField> {        return GENERIC_PHONE_REGEX.findAll(text).mapNotNull { match ->            // Skip if already matched as Indian phone.            if (text.substringBefore(match.value).endsWith("+91")) return@mapNotNull null            OcrField(                type = OcrFieldType.PHONE_NUMBER,                value = match.value,                rawText = match.value,                confidence = 0.80f,            )        }.toList()    }    /** Extract email addresses. */    internal fun extractEmails(text: String): List<OcrField> {        return EMAIL_REGEX.findAll(text).map { match ->            OcrField(                type = OcrFieldType.EMAIL,                value = match.value.lowercase(),                rawText = match.value,                confidence = 0.95f,            )        }.toList()    }    /** Extract URLs. */    internal fun extractUrls(text: String): List<OcrField> {        return URL_REGEX.findAll(text).map { match ->            OcrField(                type = OcrFieldType.URL,                value = match.value,                rawText = match.value,                confidence = 0.95f,            )        }.toList()    }    /** Extract dates (Indian format: DD/MM/YYYY or DD-MM-YYYY). */    internal fun extractDates(text: String): List<OcrField> {        return DATE_REGEX.findAll(text).map { match ->            OcrField(                type = OcrFieldType.DATE,                value = match.value,                rawText = match.value,                confidence = 0.85f,            )        }.toList()    }    /** Extract times (HH:MM AM/PM). */    internal fun extractTimes(text: String): List<OcrField> {        return TIME_REGEX.findAll(text).map { match ->            OcrField(                type = OcrFieldType.TIME,                value = match.value,                rawText = match.value,                confidence = 0.85f,            )        }.toList()    }    /** Extract generic money amounts (numbers with decimal). */    internal fun extractMoney(text: String): List<OcrField> {        return MONEY_REGEX.findAll(text).map { match ->            OcrField(                type = OcrFieldType.MONEY,                value = match.value,                rawText = match.value,                confidence = 0.75f,            )        }.toList()    }    // ═══════════════════════════════════════════════════════════════════════════    // 3. Document-specific extractors (best-effort context-based)    // ═══════════════════════════════════════════════════════════════════════════    /** Extract merchant names (text before "Receipt" or "Bill" or after "Merchant:"). */    internal fun extractMerchantNames(text: String): List<OcrField> {        val results = mutableListOf<OcrField>()        MERCHANT_REGEX.findAll(text).forEach { match ->            val name = match.groupValues.getOrNull(1)?.trim()            if (!name.isNullOrBlank() && name.length in 2..50) {                results.add(OcrField(                    type = OcrFieldType.MERCHANT_NAME,                    value = name,                    rawText = match.value,                    confidence = 0.70f,                ))            }        }        return results    }    /** Extract receipt totals (number after "Total:"). */    internal fun extractReceiptTotals(text: String): List<OcrField> {        val results = mutableListOf<OcrField>()        RECEIPT_TOTAL_REGEX.findAll(text).forEach { match ->            val amount = match.groupValues.getOrNull(1)?.trim()            if (!amount.isNullOrBlank()) {                results.add(OcrField(                    type = OcrFieldType.RECEIPT_TOTAL,                    value = amount.replace(",", ""),                    rawText = match.value,                    confidence = 0.85f,                ))            }        }        return results    }    /** Extract medicine names (common Indian medicines). */    internal fun extractMedicineNames(text: String): List<OcrField> {        val results = mutableListOf<OcrField>()        for (medicine in COMMON_MEDICINES) {            val regex = Regex("\\b${Regex.escape(medicine)}\\b", RegexOption.IGNORE_CASE)            regex.findAll(text).forEach { match ->                results.add(OcrField(                    type = OcrFieldType.MEDICINE_NAME,                    value = medicine,                    rawText = match.value,                    confidence = 0.88f,                ))            }        }        return results    }    /** Extract doctor names ("Dr. X" or "Dr X"). */    internal fun extractDoctorNames(text: String): List<OcrField> {        val results = mutableListOf<OcrField>()        DOCTOR_REGEX.findAll(text).forEach { match ->            val name = match.groupValues.getOrNull(1)?.trim()            if (!name.isNullOrBlank() && name.length in 2..50) {                results.add(OcrField(                    type = OcrFieldType.DOCTOR_NAME,                    value = name,                    rawText = match.value,                    confidence = 0.85f,                ))            }        }        return results    }    /** Extract person names (heuristic: "Name: X" or first line of business card). */    internal fun extractPersonNames(text: String): List<OcrField> {        val results = mutableListOf<OcrField>()        PERSON_NAME_REGEX.findAll(text).forEach { match ->            val name = match.groupValues.getOrNull(1)?.trim()            if (!name.isNullOrBlank() && name.length in 2..50 && name.split(" ").size in 1..4) {                results.add(OcrField(                    type = OcrFieldType.PERSON_NAME,                    value = name,                    rawText = match.value,                    confidence = 0.65f,                ))            }        }        return results    }    /** Extract organization names (heuristic: "Org: X" or text after "Inc."/"Ltd."/"Pvt Ltd"). */    internal fun extractOrganizations(text: String): List<OcrField> {        val results = mutableListOf<OcrField>()        ORG_REGEX.findAll(text).forEach { match ->            val org = match.groupValues.getOrNull(1)?.trim()            if (!org.isNullOrBlank() && org.length in 2..60) {                results.add(OcrField(                    type = OcrFieldType.ORGANIZATION,                    value = org,                    rawText = match.value,                    confidence = 0.65f,                ))            }        }        return results    }    // ═══════════════════════════════════════════════════════════════════════════    // Regex patterns (compiled once)    // ═══════════════════════════════════════════════════════════════════════════    private companion object {        private const val TAG = "OcrFieldExtractor"        // India-specific        val INDIAN_PHONE_REGEX = Regex("\\+91[\\-\\s]?\\d{10}")        val AADHAAR_REGEX = Regex("\\b\\d{4}[\\-\\s]?\\d{4}[\\-\\s]?\\d{4}\\b")        val PAN_REGEX = Regex("\\b[A-Z]{5}\\d{4}[A-Z]\\b")        val GSTIN_REGEX = Regex("\\b\\d{2}[A-Z]{5}\\d{4}[A-Z]\\d[Z][A-Z\\d]\\b")        val IFSC_REGEX = Regex("\\b[A-Z]{4}0\\d{6}\\b")        val UPI_ID_REGEX = Regex("\\b[\\w.\\-]+@[\\w.\\-]+\\b")        val INDIAN_CURRENCY_REGEX = Regex("(?:₹\\s?\\d+(?:,\\d{3})*(?:\\.\\d{1,2})?|Rs\\.?\\s?\\d+(?:,\\d{3})*(?:\\.\\d{1,2})?)")        // Generic        val GENERIC_PHONE_REGEX = Regex("\\b\\d{10}\\b")        val EMAIL_REGEX = Regex("[\\w.+-]+@[\\w-]+\\.[\\w.-]+")        val URL_REGEX = Regex("https?://\\S+")        val DATE_REGEX = Regex("\\b\\d{1,2}[/\\-]\\d{1,2}[/\\-]\\d{2,4}\\b")        val TIME_REGEX = Regex("\\b\\d{1,2}:\\d{2}(?::\\d{2})?\\s*[AP]M?\\b", RegexOption.IGNORE_CASE)        val MONEY_REGEX = Regex("\\b\\d+(?:,\\d{3})*(?:\\.\\d{1,2})?\\b")        // Document-specific        val MERCHANT_REGEX = Regex("(?:Merchant:\\s*(.+)|^(.+?)\\s+(?:Receipt|Bill|Invoice))", RegexOption.MULTILINE)        val RECEIPT_TOTAL_REGEX = Regex("(?:Total|Grand Total|Amount Due)[:\\s]*₹?\\s*(\\d+(?:,\\d{3})*(?:\\.\\d{1,2})?)", RegexOption.IGNORE_CASE)        val DOCTOR_REGEX = Regex("Dr\\.?\\s+([A-Z][a-z]+(?:\\s+[A-Z][a-z]+){0,3})")        val PERSON_NAME_REGEX = Regex("(?:Name|Patient)[:\\s]+([A-Z][a-z]+(?:\\s+[A-Z][a-z]+){0,3})")        val ORG_REGEX = Regex("(?:Org|Company)[:\\s]+(.+?)(?:\\n|$)", RegexOption.MULTILINE)        // Common Indian medicines (for prescription scanning — v3 §"Prescription Scanner")        val COMMON_MEDICINES = listOf(            // Pain/fever            "Paracetamol", "Crocin", "Dolo", "Calpol", "Combiflam", "Voveran", "Brufen", "Ibuprofen",            // Antibiotics            "Amoxicillin", "Azithromycin", "Ciprofloxacin", "Cefixime", "Augmentin", "Levofloxacin",            // Antacid/digestive            "Pantop", "Pantoprazole", "Omeprazole", "Ranitidine", "Eno", "Pudin Hara", "Digene",            // Diabetes            "Metformin", "Glimepiride", "Glycomet", "Amaryl",            // BP/heart            "Amlodipine", "Atenolol", "Losartan", "Telmisartan",            // Vitamins/supplements            "Shelcal", "Calcium", "Vitamin D3", "Becosules", "Neurobion", "Limcee",            // Allergy            "Cetirizine", "Montair", "Allegra", "Avil",            // Other            "Rantac", "Zincovit", "Evion",        )    }}